<?php
/** Proof — JSON mode (spec "Proof", 8): every handler under an action token {ok, did, record_id, location}; 422 {error:{code invalid, fields}}; 404 in a sentence; _partial=1 keeps the head; the entry and the list answer JSON. */
require __DIR__ . '/lib.php';
ensure_year(as_member(1));
$bea = ['X-Action-Token: ' . person_token(27)]; $carl = ['X-Action-Token: ' . person_token(28)]; $owner = ['X-Action-Token: ' . person_token(1)];
echo "1. The handlers answer {ok, did, record_id, location}\n";
$wrong = [];
$check = function (string $label, array $r, ?string $re = null) use (&$wrong): void { [$c, $b] = $r; if ($c !== 200 || !($b['ok'] ?? false) || !isset($b['did'], $b['location']) || ($re !== null && !preg_match($re, (string) $b['location']))) { $wrong[] = "$label $c " . msg($b) . ' ' . ($b['location'] ?? ''); } };
[$c, $b] = act_token('/journal/save.php', ['entry_date' => '2026-09-01', 'memo' => 'SMOKE json', 'lines' => json_encode([['account' => '6200', 'debit' => '20'], ['account' => '1010', 'credit' => '20']])], $bea);
$check('journal_entry_draft', [$c, $b], '#^/journal/(\d+)\?notice=saved$#');
$id = (int) ($b['record_id'] ?? 0);
$check('journal_entry_update', act_token('/journal/save.php', ['entry' => $id, 'memo' => 'SMOKE json changed'], $bea));
[$c, $b] = act_token('/journal/line-save.php', ['entry' => $id, 'account' => '6200', 'debit' => '1'], $bea);
$check('journal_line_save', [$c, $b], '#^/journal/' . $id . '\?notice=line_saved\#entry-lines$#');
$line = (int) ($b['record_id'] ?? 0);
$check('journal_line_save (change)', act_token('/journal/line-save.php', ['entry' => $id, 'line' => $line, 'credit' => '1'], $bea));
$check('journal_line_remove', act_token('/journal/line-remove.php', ['entry' => $id, 'line' => $line], $bea));
$check('journal_entry_post', act_token('/journal/post.php', ['entry' => $id], $bea), '#^/journal/' . $id . '\?notice=posted$#');
[$c, $b] = act_token('/journal/reverse.php', ['entry' => $id, 'reason' => 'SMOKE json reverse'], $bea);
$check('journal_entry_reverse', [$c, $b], '#^/journal/(\d+)\?notice=reversed$#');
[$c, $b] = act_token('/journal/save.php', ['entry_date' => '2026-09-02', 'lines' => '[]'], $bea);
$draft2 = (int) ($b['record_id'] ?? 0);
$check('journal_entry_void', act_token('/journal/void.php', ['entry' => $draft2, 'reason' => 'SMOKE'], $bea));
[$c, $b] = act_token('/journal/save.php', ['entry_date' => '2026-09-03', 'lines' => json_encode([['account' => '6200', 'debit' => '2'], ['account' => '1010', 'credit' => '2']])], $bea);
$check('journal_entries_post_batch', act_token('/journal/post-batch.php', ['entries' => (string) $b['record_id']], $bea), '#^/journal/\?notice=posted_batch$#');
$check('note_add', act_token('/notes/save.php', ['record_type' => 'journal_entry', 'record_id' => $id, 'body' => 'SMOKE json note'], $bea), '#^/journal/' . $id . '\?notice=noted\#note-(\d+)$#');
ok($wrong === [], '11 handlers answer {ok, did, location}' . ($wrong ? ' — wrong: ' . implode('; ', $wrong) : ''));
[$c, $b, $raw] = act_token('/journal/save.php', ['entry_date' => '2026-09-04', 'lines' => '[]'], $bea);
ok(!str_contains($raw['headers'], 'Set-Cookie'), 'a token request opens no session');
echo "2. Refusals\n";
[$c, $b] = act_token('/journal/save.php', ['entry_date' => 'x', 'department' => '424242', 'lines' => '[]'], $bea);
$f = fields($b);
ok($c === 422 && ($b['error']['code'] ?? '') === 'invalid' && isset($f['entry_date'], $f['department']) && count($b['error']['errors']) === 2, 'a bad form: 422 {error: {code invalid, errors[2], fields{entry_date, department}}}');
[$c, $b] = act_token('/journal/post.php', ['entry' => 424242], $bea);
ok($c === 404 && msg($b) === 'Entry not found.', 'an unknown entry: 404 "Entry not found."');
[$c, $b] = act_token('/journal/post.php', ['entry' => $id], ['X-Action-Token: ' . person_token(26)]);
ok($c === 403 && msg($b) === 'You may not write journal entries.', 'a Viewer posting: 403 in the right\'s sentence');
[$c, $b] = act_token('/journal/save.php', ['entry_date' => '2026-09-05', 'lines' => 'not json'], $bea);
ok($c === 422 && str_contains(msg($b), 'lines is a JSON list'), 'lines that is not JSON: 422');
echo "3. _partial=1 keeps the head\n";
[$c, $b] = act_token('/journal/save.php', ['entry_date' => '2026-09-06', 'memo' => 'SMOKE partial', 'department' => 3, 'lines' => '[]'], $bea);
$p = (int) $b['record_id'];
[$c, $b] = act_token('/journal/save.php', ['entry' => $p, 'memo' => 'SMOKE partial renamed', '_partial' => '1'], $bea);
ok($c === 200 && q('SELECT memo, department_id, entry_date FROM journal_entries WHERE id = :i', ['i' => $p])[0] == ['memo' => 'SMOKE partial renamed', 'department_id' => 3, 'entry_date' => '2026-09-06'], 'journal_entry_update with _partial=1: the base row fills the rest');
echo "4. The screens answer JSON\n";
$r = req('GET', '/journal/' . $id, ['headers' => array_merge(JSONH, $bea)]);
$d = json_decode($r['body'], true)['data'] ?? [];
ok($r['code'] === 200 && $d['entry']['journal_entry_id'] === $id && is_array($d['entry']['lines']) && isset($d['balance'], $d['attachments'], $d['notes'], $d['timeline'], $d['may']), 'the entry: entry (with lines), balance, attachments, notes, timeline, may');
$r = req('GET', '/journal/?status=posted', ['headers' => array_merge(JSONH, $bea)]);
$d = json_decode($r['body'], true)['data'] ?? [];
ok($r['code'] === 200 && isset($d['entries'], $d['total'], $d['totals'], $d['filters']) && $d['filters']['status'] === 'posted', 'the list: entries, total, totals, filters');
$r = req('GET', '/journal/new', ['headers' => array_merge(JSONH, $bea)]);
ok($r['code'] === 200 && isset(json_decode($r['body'], true)['data']['departments']), 'the form answers its choices');
finish();
